              banca: "Estilo IBFC · Múltipla escolha",
              tipo: "multi",
              enunciado: "Nos termos do art. 5º, LXVIII, da CF/88, conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder.",
