              enunciado: "Nos termos do caput do art. 6º da CF/88, com a redação da EC 90/2015, são direitos sociais a educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer, a segurança, a previdência social, a proteção à maternidade e à infância, a assistência aos desamparados, na forma desta Constituição.",
