          title: "ARTIGO 7º — BLOCO 5 (incisos XXXI a XXXIV + parágrafo único)",
          rows: [
            { k: "Art. 7º, XXXI — proibição de discriminação do trabalhador com deficiência ⭐⭐", v: "**Texto:** 'proibição de qualquer discriminação no tocante a salário e critérios de admissão do trabalhador portador de deficiência;' · **Explicação:** dupla proibição relativa ao trabalhador com deficiência: salário e critérios de ADMISSIONAIS. Complementos: Lei 8.213/91, art. 93 (cota de 2% a 5% de cargos em empresas com 100+ empregados); LBI — Lei 13.146/2015 (trabalho em igualdade de condições; adaptações razoáveis). O texto constitucional usa a expressão da época ('portador de deficiência'). · **Alcance:** trabalhadores com deficiência. · **STF:** pacífico quanto ao caráter antidiscriminatório; cota legal é constitucional. · **PMPE:** nos concursos da PMPE, vagas reservadas a pessoas com deficiência (legislação estadual) e adaptações de prova; a discriminação salarial/admissional de servidor civil da corporação é ilegal. · **Memorize:** 2 objetos vedados à discriminação: salário + critérios de admissão; LBI 13.146/15. · **Pegadinha:** confundir com o XXX (motivos: sexo/idade/cor/estado civil) — o XXXI trata especificamente de deficiência." },
            { k: "Art. 7º, XXXII — proibição de distinção entre trabalho manual, técnico e intelectual ⭐⭐", v: "**Texto:** 'proibição de distinção entre trabalho manual, técnico e intelectual ou entre os profissionais respectivos;' · **Explicação:** dignidade IGUAL das três formas de trabalho — manual, técnico e intelectual — e de seus profissionais. Impede hierarquizar valor social pelo tipo de trabalho (ex.: estabelecer pisos de cidadania distintos por natureza do ofício). Não impede DIFERENÇAS salariais legítimas por função, complexidade ou produtividade (V — piso proporcional). · **Alcance:** todos os trabalhadores. · **STF:** Sem jurisprudência pacífica específica para fins de prova. · **PMPE:** na corporação, operacionais e administrativos têm igual dignidade institucional; distinções legítimas são funcionais (grau, função), não de natureza do trabalho. · **Memorize:** manual = técnico = intelectual (igual dignidade); proíbe DISTINÇÃO, não diferenciação funcional legítima. · **Pegadinha:** 'proíbe qualquer diferença salarial entre atividades manuais e intelectuais' (proíbe DISTINÇÃO de valor; diferenças funcionais legítimas permanecem)." },
            { k: "Art. 7º, XXXIII — proibição de trabalho ao menor ⭐⭐⭐", v: "**Texto:** 'proibição de trabalho noturno, perigoso ou insalubre a menores de dezoito e de qualquer trabalho a menores de dezesseis anos, salvo na condição de aprendiz, a partir de quatorze anos;' · **Explicação:** redação da EC 20/1998 (antes: qualquer trabalho a menores de 14). Regra dupla: ① menores de 18: vedados trabalho NOTURNO, PERIGOSO ou INSALUBRE; ② menores de 16: vedado QUALQUER trabalho — SALVO aprendiz a partir de 14 ANOS (aprendiz: 14 a 17 — Lei 10.097/2000). Harmonia com o ECA (arts. 403 e seguintes) e com o art. 227. · **Alcance:** menores de 18 anos. · **STF:** pacífico quanto ao caráter protetivo; Lei 14.811/2024 endureceu o tratamento penal da exploração de trabalho infantil. · **PMPE:** diligências em locais de trabalho: verificar idade de menores empregados; trabalho de menor de 16 (fora de aprendizagem) ou noturno/insalubre/perigoso de menor de 18 = infração a ser apurada (apreensão de documentos, comunicação ao Conselho Tutelar). · **Memorize:** <18: noturno/perigoso/insalubre VEDADO; <16: qualquer trabalho VEDADO; aprendiz: desde 14. · **Pegadinha:** 'aprendiz a partir de 12 anos' (a idade mínima constitucional é 14 — EC 20/1998) ou omitir a vedação do noturno/perigoso/insalubre para os menores de 18." },
            { k: "Art. 7º, XXXIV — igualdade entre empregado permanente e trabalhador avulso ⭐⭐", v: "**Texto:** 'igualdade de direitos entre o trabalhador com vínculo empregatício permanente e o trabalhador avulso' · **Explicação:** o trabalhador AVULSO (portuário — OGMO/Órgão Gestor de Mão de Obra; Lei 12.023/2009 — e similares) tem os MESMOS direitos do empregado permanente comparável. O avulso não tem empregador fixo: é tomado a cada turno pelo intermediação do OGMO. Objetivo: impedir precarização pela intermediação. · **Alcance:** trabalhadores avulsos portuários e assemelhados. · **STF:** pacífico quanto à paridade de direitos essenciais. · **PMPE:** fiscalização de portos e terminais pode envolver a PM em apoio; o conceito de avulso cai em prova como definição. · **Memorize:** avulso = paridade com o permanente; intermediação obrigatória pelo OGMO (portos). · **Pegadinha:** 'o avulso tem metade dos direitos' (paridade) ou confundir avulso com temporário (Lei 6.019/74 — regime distinto)." },
            { k: "Art. 7º, parágrafo único — trabalhadores domésticos (EC 72/2013) ⭐⭐⭐", v: "**Texto:** 'São assegurados à categoria dos trabalhadores domésticos os direitos previstos nos incisos IV, VI, VII, VIII, X, XIII, XV, XVI, XVII, XVIII, XIX, XXI, XXII, XXIV, XXVI, XXX, XXXI e XXXIII e, atendidas as condições estabelecidas em lei e observada a simplificação do cumprimento das obrigações tributárias, principais e acessórias, decorrentes da relação de trabalho e suas peculiaridades, os previstos nos incisos I, II, III, IX, XII, XXV e XXVIII, bem como a sua integração à previdência social.' (redação da **EC 72/2013**) · **Explicação:** marco dos direitos domésticos. GRUPO 1 — direitos DIRETOS (18 incisos): IV (mínimo), VI (irredutibilidade), VII (variável), VIII (13º), X (proteção salarial/crime), XIII (8h/44h), XV (DSR), XVI (hora extra ≥50%), XVII (férias+1/3), XVIII (gestante 120d), XIX (paternidade), XXI (aviso prévio), XXII (riscos), XXIV (aposentadoria), XXVI (negociação coletiva), XXX (anti-discriminação), XXXI (deficiência), XXXIII (menor). GRUPO 2 — direitos CONDICIONADOS à lei (7 incisos): I (indemnização FGTS), II (seguro-desemprego), III (FGTS), IX (noturno), XII (salário-família), XXV (creche), XXVIII (seguro acidentes). + integração previdenciária. Regulamento: **Lei 150/2015** (SIMPLES doméstico, FGTS, seguro-desemprego de 4 parcelas etc.); ADC 58: contribuição patronal de 8,2% do SIMPLES é constitucional. Antes da EC 72, o § único de 1988 dava só 9 direitos (IV, VI, VIII, XV, XVII, XVIII, XIX, XXI e XXIV). · **Alcance:** trabalhadores domésticos (serviços de forma contínua, subordinada, onerosa e em âmbito residencial — L 150/15, art. 1º). · **STF:** ADC 58 (constitucionalidade do SIMPLES doméstico). · **PMPE:** a casa de policial que contrata empregada doméstica deve seguir a L 150/15 (eSocial doméstico); institucionalmente, o conceito cai em prova. · **Memorize:** EC 72/2013; 18 direitos diretos + 7 condicionados à lei + previdência; L 150/2015. · **Pegadinha:** atribuir ao § único a redação antiga (9 incisos); incluir seguro acidentes (XXVIII) nos diretos (é CONDICIONADO) ou omitir o aviso prévio (XXI) dos diretos." },
          ],
